export const BRANCH_ABILITIES=[{"name":"Incomplete Soul","class":"Standard","text":"Species trait: receives 50% of the final EXP it would normally receive, including participation, capture EXP and binocular sharing. A single 2× Warbond multiplier brings this to normal EXP. The penalty ends upon evolution; changing abilities cannot bypass it."},{"name":"Peerless Ego","class":"Standard","text":"special damage rises by 20% while no combat stat is lowered. A stat drop removes the bonus until all lowered stages are cleared."},{"name":"Grievance","class":"Standard","text":"after surviving a super-effective damaging hit, gain one Attack stage. At most once per attack, including multi-hit moves."},{"name":"Unhurried","class":"Standard","text":"reduce direct damage taken by 20% while moving after the attacker. Residual damage is unchanged; no forced loafing turns."},{"name":"Bottomless","class":"Standard","text":"healing from draining attacks is 25% stronger. The existing healing multiplier and maximum HP still apply; it cannot revive or grant lives."},{"name":"Quick Study","class":"Standard","text":"the first lowered combat stat in each battle is restored immediately to its previous stage. Once per battle."},{"name":"Sovereign Charge","class":"Standard","text":"the first successful damaging move after each entry deals 25% extra damage. Switching resets it; missed or blocked attacks do not spend it."},{"name":"Burhwall","class":"Standard","text":"reduce super-effective damage received by 25%. Does not affect status or indirect damage."},{"name":"Heavy Hands","class":"Standard","text":"contact attacks deal 15% more damage but the user cannot gain evasion stages. Does not boost non-contact moves."},{"name":"The Fixer","class":"Standard","text":"after using a non-damaging move, its living active ally gains one Speed stage once per turn. In singles, prepare that bonus for the next voluntary incoming partner; it cannot stack before the switch."}];
