export function isHellRegion(room){return /^(hell|inferno|underworld|nether)(?:[A-Z_0-9-]|$)/i.test(String(room||''));}
export function branchEvolutionAllowed(path,state){return path.condition.region!=='HELL'||isHellRegion(state.evolutionRoom);}
export function installBranchFamilies(data){
 if(data.species.some(s=>s.id==='505'))return;data.species.push(...BRANCH_SPECIES);data.moves.push(...BRANCH_MOVES);
 const rows=[...BRANCH_INITIAL_LEARNSETS];
 for(const species of BRANCH_SPECIES){if(species.id==='505')continue;
 const names=BRANCH_POOLS[species.id]||[];for(let i=0;i<names.length;i++){const m=data.moves.find(m=>m.name===names[i]);if(m)rows.push({species_id:species.id,move_id:m.id,level:i<3?(species.stage==='Final'?0:1):8+(i-3)*5,method:'LEVEL_UP',branchFamily:true});}
 }
 data.learnsets.push(...rows);data.authoredLearnsets?.push(...rows.map(l=>({...l})));for(const s of BRANCH_SPECIES)data.assets.push({id:s.id,runtime:'assets/'+s.id+'.webp',source:'approved branch-family art'});
}
