export function branchEncounterRoute(route){if(!route?.tables||route.branchExpanded)return route;const h={scrub:{id:'505',min:5,max:8},northRoad:{id:'510',min:8,max:12}}[route.room];if(!h)return route;return {...route,branchExpanded:true,tables:route.tables.map(t=>{const slots=t.slots.map(s=>({...s})),donor=slots.reduce((a,b)=>a.weight>b.weight?a:b);donor.weight-=4;slots.push({species_id:h.id,min_level:h.min,max_level:h.max,weight:4,rarity:'Rare',authoredSlot:true});return {...t,slots};})};}
